const listDealerFleets = `-- name: ListDealerFleets :many
WITH fl AS (
    SELECT l.id AS link_id, l.uuid AS link_uuid, l.status AS link_status,
           l.started_at, l.ended_at, l.created_at,
           l.cari_account_id, l.dealer_org_id,
           d.uuid AS dealer_uuid, d.name AS dealer_name,
           f.id AS fleet_org_id, f.uuid AS fleet_uuid, f.name, f.status AS fleet_status,
           fp.tax_number, fp.legal_name,
           (SELECT COUNT(*) FROM vehicles v
            WHERE v.fleet_org_id = f.id AND v.deleted_at IS NULL)::bigint AS vehicle_count,
           (SELECT MAX(s.completed_at) FROM services s
            JOIN vehicles v ON v.id = s.vehicle_id
            WHERE v.fleet_org_id = f.id AND s.organization_id = l.dealer_org_id
              AND s.status = 'completed')::timestamptz AS last_service_at
    FROM fleet_dealer_links l
    JOIN organizations f ON f.id = l.fleet_org_id AND f.deleted_at IS NULL
    JOIN organizations d ON d.id = l.dealer_org_id
    JOIN fleet_profiles fp ON fp.organization_id = f.id
    WHERE l.brand_id = $7
      AND ($8::bigint[] IS NULL OR l.dealer_org_id = ANY ($8::bigint[]))
      AND (
        COALESCE(cardinality($9::text[]), 0) = 0
        OR l.status = ANY ($9::text[])
      )
      AND (
        $10::text IS NULL
        OR f.name ILIKE '%' || $10 || '%'
        OR fp.legal_name ILIKE '%' || $10 || '%'
        OR fp.tax_number LIKE $10 || '%'
      )
)
SELECT link_id, link_uuid, link_status, started_at, ended_at, created_at, cari_account_id, dealer_org_id, dealer_uuid, dealer_name, fleet_org_id, fleet_uuid, name, fleet_status, tax_number, legal_name, vehicle_count, last_service_at FROM fl
WHERE ($1::bigint IS NULL OR fl.vehicle_count >= $1)
  AND ($2::bigint IS NULL OR fl.vehicle_count <= $2)
ORDER BY
  CASE WHEN NOT $3::bool AND $4::text = 'name' THEN fl.name END ASC,
  CASE WHEN $3::bool AND $4::text = 'name' THEN fl.name END DESC,
  CASE WHEN NOT $3::bool AND $4::text = 'vehicle_count' THEN fl.vehicle_count END ASC,
  CASE WHEN $3::bool AND $4::text = 'vehicle_count' THEN fl.vehicle_count END DESC,
  CASE WHEN NOT $3::bool AND $4::text = 'created_at' THEN fl.created_at END ASC,
  CASE WHEN $3::bool AND $4::text = 'created_at' THEN fl.created_at END DESC,
  -- Nullable column: its own pair so NULLS LAST does not affect the others.
  CASE WHEN NOT $3::bool AND $4::text = 'last_service_at' THEN fl.last_service_at END ASC NULLS LAST,
  CASE WHEN $3::bool AND $4::text = 'last_service_at' THEN fl.last_service_at END DESC NULLS LAST,
  CASE WHEN $3::bool THEN fl.link_id END DESC,
  fl.link_id ASC
LIMIT $6 OFFSET $5
`

