const listFleetVehicles = `-- name: ListFleetVehicles :many
WITH fv AS (
    SELECT v.id, v.uuid, v.user_id, v.plate, v.plate_country, v.vin, v.model_year, v.created_at,
           cb.uuid AS car_brand_uuid, cb.name AS car_brand_name,
           cm.uuid AS car_model_uuid, cm.name AS car_model_name,
           (SELECT MAX(s.completed_at) FROM services s
            WHERE s.vehicle_id = v.id AND s.status = 'completed'
              AND ($5::bigint[] IS NULL
                   OR s.organization_id = ANY ($5::bigint[])))::timestamptz AS last_service_at,
           (SELECT COUNT(*) FROM warranties w
            WHERE w.vehicle_id = v.id AND w.status = 'active' AND w.end_at > NOW()
              AND ($5::bigint[] IS NULL
                   OR w.organization_id = ANY ($5::bigint[])))::bigint AS active_warranty_count
    FROM vehicles v
    LEFT JOIN car_brands cb ON cb.id = v.car_brand_id
    LEFT JOIN car_models cm ON cm.id = v.car_model_id
    WHERE v.fleet_org_id = $6::bigint AND v.deleted_at IS NULL
      AND (
        $7::text IS NULL
        OR v.plate ILIKE '%' || $7 || '%'
        OR v.plate_normalized LIKE $8::text || '%'
        OR v.vin ILIKE $7 || '%'
        OR cb.name ILIKE '%' || $7 || '%'
        OR cm.name ILIKE '%' || $7 || '%'
      )
)
SELECT id, uuid, user_id, plate, plate_country, vin, model_year, created_at, car_brand_uuid, car_brand_name, car_model_uuid, car_model_name, last_service_at, active_warranty_count FROM fv
ORDER BY
  CASE WHEN NOT $1::bool AND $2::text = 'plate' THEN fv.plate END ASC NULLS LAST,
  CASE WHEN $1::bool AND $2::text = 'plate' THEN fv.plate END DESC NULLS LAST,
  CASE WHEN NOT $1::bool AND $2::text = 'car_brand' THEN fv.car_brand_name END ASC NULLS LAST,
  CASE WHEN $1::bool AND $2::text = 'car_brand' THEN fv.car_brand_name END DESC NULLS LAST,
  CASE WHEN NOT $1::bool AND $2::text = 'last_service_at' THEN fv.last_service_at END ASC NULLS LAST,
  CASE WHEN $1::bool AND $2::text = 'last_service_at' THEN fv.last_service_at END DESC NULLS LAST,
  CASE WHEN NOT $1::bool AND $2::text = 'active_warranty_count' THEN fv.active_warranty_count END ASC,
  CASE WHEN $1::bool AND $2::text = 'active_warranty_count' THEN fv.active_warranty_count END DESC,
  CASE WHEN NOT $1::bool AND $2::text = 'created_at' THEN fv.created_at END ASC,
  CASE WHEN $1::bool AND $2::text = 'created_at' THEN fv.created_at END DESC,
  CASE WHEN $1::bool THEN fv.id END DESC,
  fv.id ASC
LIMIT $4 OFFSET $3
`

